<?php require_once '../config/db.php';require_once '../includes/auth.php';require_role('admin');$rows=$pdo->query("SELECT s.name subject_name,COUNT(m.id) material_count FROM subjects s LEFT JOIN materials m ON m.subject_id=s.id GROUP BY s.id ORDER BY material_count DESC")->fetchAll();$page_title='Reports';$css_path='../assets/css/style.css';$home_path='dashboard.php';$logout_path='../logout.php';$role='admin';include '../includes/header.php';?><div class="layout"><?php include '../includes/sidebar.php';?><h1 class="page-title">Reports</h1><div class="table-card"><table><thead><tr><th>Subject</th><th>Materials</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['subject_name'])?></td><td><?=$r['material_count']?></td></tr><?php endforeach;?></tbody></table></div></main></div><?php include '../includes/footer.php';?>